// The golden files were generated by ec0af78, before OTLP port support.
// Sort only the Service lists: their order comes from maps on main too.
func TestAggregatorWithoutRoleMatchesMain(t *testing.T) {
	g := NewWithT(t)
	var fixtures []struct {
		Name      string
		Cluster   bool
		Pipelines []vectorv1alpha1.VectorPipeline
	}
	dir := filepath.Join("testdata", "no_role")
	data, err := os.ReadFile(filepath.Join(dir, "pipelines.json"))
	g.Expect(err).To(Succeed())
	g.Expect(json.Unmarshal(data, &fixtures)).To(Succeed())
	for _, fixture := range fixtures {
		t.Run(fixture.Name, func(t *testing.T) {
			g := NewWithT(t)
			var pipelines []pipeline.Pipeline
			for _, p := range fixture.Pipelines {
				g.Expect(p.Spec.Role).To(BeNil())
				var parsed config.PipelineConfig
				g.Expect(config.UnmarshalJson(p.Spec, &parsed)).To(Succeed())
				role, err := parsed.VectorRole(nil)
				g.Expect(err).To(Succeed())
				g.Expect(*role).To(Equal(vectorv1alpha1.VectorPipelineRoleAggregator))
				p.SetRole(role)
				if fixture.Cluster {
					pipelines = append(pipelines, &vectorv1alpha1.ClusterVectorPipeline{
						ObjectMeta: p.ObjectMeta, Spec: p.Spec, Status: p.Status,
					})
				} else {
					pipelines = append(pipelines, &p)
				}
			}
			cfg, err := config.BuildAggregatorConfig(config.VectorConfigParams{AggregatorName: "test"}, pipelines...)
			g.Expect(err).To(Succeed())
			configBytes, err := cfg.MarshalJSON()
			g.Expect(err).To(Succeed())
			ctrl := NewController(&vectorv1alpha1.VectorAggregator{
				ObjectMeta: metav1.ObjectMeta{Name: "test", Namespace: "logs"},
			}, nil, nil)
			ctrl.Config = cfg
			services, err := ctrl.createVectorAggregatorServices()
			g.Expect(err).To(Succeed())
			type service struct {
				Name      string               `json:"name"`
				Namespace string               `json:"namespace"`
				Ports     []corev1.ServicePort `json:"ports"`
			}
			got := make([]service, 0, len(services))
			for _, s := range services {
				got = append(got, service{s.Name, s.Namespace, s.Spec.Ports})
			}
			slices.SortFunc(got, func(a, b service) int { return cmp.Compare(a.Name, b.Name) })
			serviceBytes, err := json.MarshalIndent(got, "", "  ")
			g.Expect(err).To(Succeed())
			for suffix, actual := range map[string][]byte{"config": configBytes, "services": serviceBytes} {
				expected, err := os.ReadFile(filepath.Join(dir, fixture.Name+"."+suffix+".json"))
				g.Expect(err).To(Succeed())
				g.Expect(string(actual)).To(Equal(string(expected)), suffix)
			}
		})
	}
}

func TestServicePortsKeepInputOrder(t *testing.T) {
	g := NewWithT(t)
	list := []*config.ServicePort{
		{SourceName: "legacy_input", Port: 9000, Protocol: corev1.ProtocolTCP},
		{SourceName: "udp_input", Port: 6000, Protocol: corev1.ProtocolUDP},
		{SourceName: "tcp_input", Port: 6000, Protocol: corev1.ProtocolTCP},
	}
	want := []corev1.ServicePort{
		{Name: "legacy-input", Protocol: corev1.ProtocolTCP, Port: 9000, TargetPort: intstr.FromInt32(9000)},
		{Name: "udp-input", Protocol: corev1.ProtocolUDP, Port: 6000, TargetPort: intstr.FromInt32(6000)},
		{Name: "tcp-input", Protocol: corev1.ProtocolTCP, Port: 6000, TargetPort: intstr.FromInt32(6000)},
	}
	g.Expect(buildServicePorts(list)).To(Equal(want))
	slices.Reverse(list)
	slices.Reverse(want)
	g.Expect(buildServicePorts(list)).To(Equal(want))
}
